CREATE OR REPLACE FUNCTION public.edit_message(p_message_id UUID, p_new_content TEXT) RETURNS public.messages LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS 'DECLARE v_msg public.messages; v_profile_id UUID; BEGIN SELECT id INTO v_profile_id FROM public.profiles WHERE auth_id = auth.uid() LIMIT 1; IF v_profile_id IS NULL THEN RAISE EXCEPTION ''profile not found''; END IF; SELECT * INTO v_msg FROM public.messages WHERE id = p_message_id; IF v_msg.id IS NULL THEN RAISE EXCEPTION ''message not found''; END IF; IF v_msg.sender_id <> v_profile_id THEN RAISE EXCEPTION ''not your message''; END IF; IF v_msg.created_at < now() - INTERVAL ''15 minutes'' THEN RAISE EXCEPTION ''edit window expired''; END IF; IF COALESCE(v_msg.is_deleted, false) THEN RAISE EXCEPTION ''cannot edit deleted message''; END IF; UPDATE public.messages SET content = p_new_content, is_edited = true, edited_at = now() WHERE id = p_message_id RETURNING * INTO v_msg; RETURN v_msg; END;'; GRANT EXECUTE ON FUNCTION public.edit_message(UUID, TEXT) TO authenticated;